draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Zone of Proximal Development (ZPD) representation
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100 + 50*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // Learner stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 + 120*Math.cos(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 120*Math.cos(t), H/2 + 20);
  ctx.lineTo(W/2 + 120*Math.cos(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 120*Math.cos(t), H/2 + 50);
  ctx.lineTo(W/2 + 120*Math.cos(t) - 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 120*Math.cos(t), H/2 + 50);
  ctx.lineTo(W/2 + 120*Math.cos(t) + 30, H/2 + 30);
  ctx.stroke();

  // More Knowledgeable Other (MKO) stick figure
  ctx.beginPath();
  ctx.arc(W/2 + 80*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80*Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 80*Math.sin(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 80*Math.sin(t) - 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 80*Math.sin(t) + 30, H/2 + 30);
  ctx.stroke();

  ctx.restore();
}
